/** 缺省中文翻译：键缺省回退为键名；params 做 `{name}` 插值（对齐 locale.bind 的语义）。 */
export function ceoT(key: string, params?: Record<string, unknown>): string {
  let text = ZH[key] ?? key
  if (params !== undefined) {
    for (const [name, value] of Object.entries(params)) {
      text = text.replaceAll(`{${name}}`, String(value))
    }
  }
  return text
}